Feature: Loyalty discount

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4).
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so no scenario exists for it.
  #   Open question for the business: what reduction does a Platinum customer get?
  # NOT DECIDED: the reduction of any other subtotal than the ones below (only AC-4 fixes a rounding case).

  @discount @happy-path @smoke
  Scenario: Bronze customer is charged the discounted basket total
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @discount @happy-path
  Scenario: Silver customer is charged the discounted basket total
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @discount @happy-path
  Scenario: Gold customer is charged the discounted basket total
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @discount @edge-case
  Scenario: Bronze customer is charged a whole cent in their favour on a small basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_discounted_basket_total()
    {
        // Bronze customer is charged the discounted basket total
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
E
